begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n),'is_anonymous',false)::text,true)$$;
create function pg_temp.payload(n integer) returns jsonb language sql as $$select jsonb_build_object('version',1,'transactionId',pg_temp.i(n),'organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'deviceId',pg_temp.i(501),'cashierId',auth.uid(),'shiftId',(select id from public.cashier_shifts where cashier_id=auth.uid() and device_id=pg_temp.i(501) and closed_at is null),'occurredAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'total',75000,'cashReceived',100000,'items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(301),'unitId',pg_temp.i(401),'batchId',null,'name','Grower feeds','unitName','Sack','quantity','0.5','factor','50','unitPrice',150000,'unitCost',120000,'priceVersion',1,'lineTotal',75000)))$$;

create function pg_temp.ctx(b integer default 101) returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(b))$$;
create function pg_temp.transfer_receipt(q text default '30') returns jsonb language sql as $$select pg_temp.ctx(102)||jsonb_build_object('transferId',pg_temp.i(801),'receiptId',pg_temp.i(802),'quantity',q,'heldQuantity','10','reason','TEST physical count: 30 saleable, 10 damaged, 10 missing')$$;
create function pg_temp.stock(b integer default 101) returns text language sql as $$select quantity::text from public.branch_inventory where branch_id=pg_temp.i(b) and product_id=pg_temp.i(301) and batch_id is null$$;
create function pg_temp.plan(saleid integer default 701) returns jsonb language sql as $$select public.agri_command('partial_refund_plan',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid)))$$;
create function pg_temp.refund(ident integer,q text default '0.2',t text default '0',d text default 'not_returned',saleid integer default 701) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid),'refundId',pg_temp.i(ident),'shiftId',(select id from public.cashier_shifts where closed_at is null and branch_id=pg_temp.i(101)),'reference','TEST signed partial refund','reason','TEST inspected physical return and original cash amount','physicalConfirmed',true,'expectedRefundVersion',pg_temp.plan(saleid)->'version','expectedAmount',round((pg_temp.plan(saleid)->'lines'->0->>'lineTotal')::numeric*((pg_temp.plan(saleid)->'lines'->0->>'refundedQuantity')::numeric+q::numeric)/(pg_temp.plan(saleid)->'lines'->0->>'quantity')::numeric)::bigint-(pg_temp.plan(saleid)->'lines'->0->>'refundedAmount')::bigint,'items',jsonb_build_array(jsonb_build_object('lineIndex',0,'quantity',q,'returnedQuantity',t,'disposition',d)))$$;
create temporary table saved(name text primary key,data jsonb);grant all on saved to authenticated;


create function pg_temp.loss_report() returns jsonb language sql as $$select public.agri_command('stock_loss_report',pg_temp.ctx()||'{"filter":"all"}'::jsonb)$$;
create function pg_temp.issue(n integer,p integer,q text,d text default 'write_off',cat text default 'damage') returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(n),'productId',pg_temp.i(p),'batchId',null,'quantity',q,'category',cat,'disposition',d,'reason','TEST physically measured goods and documented cause')$$;
create function pg_temp.outcome(n integer,q text,d text) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('holdId',(select id from public.stock_holds where source_id=pg_temp.i(801)),'dispositionId',pg_temp.i(n),'quantity',q,'disposition',d,'reason','TEST actual inspected measured held goods')$$;
create function pg_temp.loss_key(n integer) returns text language sql as $$select 'movement:'||id from public.inventory_movements where source_id=pg_temp.i(n) and kind='loss'$$;
create function pg_temp.document(key text,n integer,u integer,c text,previous integer default null) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('lossKey',key,'costEvidenceId',pg_temp.i(n),'expectedCostId',case when previous is null then null else pg_temp.i(previous) end,'unitId',pg_temp.i(u),'unitCostCentavos',c,'zeroCostConfirmed',false,'reference','TEST measured supplier invoice','reason','TEST documented purchase cost per actual roll or container')$$;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('receive_stock',pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(850),'source','purchase','reference','TEST measured loss opening','items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(311),'unitId',pg_temp.i(414),'quantity','1'),jsonb_build_object('productId',pg_temp.i(312),'unitId',pg_temp.i(415),'quantity','20'))));
select pg_temp.login(13);select public.agri_command('record_stock_issue',pg_temp.issue(801,312,'0.25','hold'));
select pg_temp.login(12);
select pg_temp.login(11);select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(801),'reason','TEST owner approved 250 ml inspection hold'));
select public.agri_command('disposition_hold',pg_temp.outcome(802,'0.1','release'));
select public.agri_command('disposition_hold',pg_temp.outcome(803,'0.125','dispose'));
select public.agri_command('disposition_hold',pg_temp.outcome(804,'0.025','supplier_return'));
select public.agri_command('record_stock_issue',pg_temp.issue(805,311,'0.25'));select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(805),'reason','TEST owner checked quarter meter damaged'));
select public.agri_command('record_stock_issue',pg_temp.issue(806,312,'0.05','write_off','spillage'));select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(806),'reason','TEST owner checked 50 ml spill'));
select public.agri_command('record_loss_cost',pg_temp.document('held:'||pg_temp.i(803),950,415,'2500'));
select public.agri_command('record_loss_cost',pg_temp.document(pg_temp.loss_key(805),951,414,'100000'));
select public.agri_command('record_loss_cost',pg_temp.document(pg_temp.loss_key(806),952,415,'2500'));
select public.agri_command('record_loss_cost',pg_temp.document('held:'||pg_temp.i(804),953,415,'2500'));
select public.agri_command('record_loss_cost',pg_temp.document('held:'||pg_temp.i(803),954,415,'3000',950));
select public.agri_command('record_stock_issue',pg_temp.issue(807,312,'0.249','write_off','spillage'));select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(807),'reason','TEST owner checked 249 ml spill'));
select public.agri_command('record_stock_issue',pg_temp.issue(808,312,'0.25','write_off','spillage'));select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(808),'reason','TEST owner checked 250 ml spill'));
select public.agri_command('record_loss_cost',pg_temp.document(pg_temp.loss_key(807),955,415,'3'));select public.agri_command('record_loss_cost',pg_temp.document(pg_temp.loss_key(808),956,415,'3'));
reset role;
set local role authenticated;select pg_temp.login(11);
reset role;select line from tap_results;select * from finish();rollback;
