insert into tap_results select is((with ledger as(select organization_id,branch_id,product_id,coalesce(batch_id,'00000000-0000-0000-0000-000000000000'::uuid) batch_key,sum(quantity) quantity from public.inventory_movements group by 1,2,3,4) select count(*) from ledger l full join public.branch_inventory i using(organization_id,branch_id,product_id,batch_key) where coalesce(l.quantity,0)<>coalesce(i.quantity,0)),0::bigint,'Every measured damage and held-stock projection matches the immutable ledger');
